{
  "sql": "SELECT rango_retraso, COUNT(*) AS pedidos, ROUND(100.0 * SUM(CASE WHEN review_score <= 2 THEN 1 ELSE 0 END) / COUNT(*), 2) AS pct_2_o_menos, ROUND(100.0 * SUM(CASE WHEN review_score <= 2 THEN 1 ELSE 0 END) / COUNT(*)) / ROUND(100.0 * SUM(CASE WHEN review_score <= 2 THEN 1 ELSE 0 END) / COUNT(*), 2) AS pct_2_o_menos_atiempo FROM (SELECT CASE WHEN julianday(order_delivered_customer_date) - julianday(order_estimated_delivery_date) <= 0 THEN 'a_tiempo' WHEN julianday(order_delivered_customer_date) - julianday(order_estimated_delivery_date) <= 3 THEN '1-3' WHEN julianday(order_delivered_customer_date) - julianday(order_estimated_delivery_date) <= 7 THEN '4-7' WHEN julianday(order_delivered_customer_date) - julianday(order_estimated_delivery_date) <= 14 THEN '8-14' ELSE '15+' END AS rango_retraso, AVG(review_score) AS review_score, COUNT(*) AS pedidos FROM vw_pedidos_validos p LEFT JOIN order_reviews rv ON rv.order_id = p.order_id GROUP BY rango_retraso) AS subquery GROUP BY rango_retraso ORDER BY pedidos DESC"
}

{
  "sql": "SELECT categoria_ingles, ROUND(100.0 * SUM(CASE WHEN COUNT(DISTINCT order_id) > 100 THEN COUNT(CASE WHEN MAX(payment_installments) > 1 THEN order_id ELSE NULL END) ELSE 0 END) / COUNT(DISTINCT order_id), 2) AS porcentaje FROM (SELECT oi.order_id, p.product_category_name_english AS categoria_ingles FROM order_items oi INNER JOIN products p ON oi.product_id = p.product_id INNER JOIN order_payments op ON oi.order_id = op.order_id WHERE op.payment_type != 'not_defined' AND oi.order_id IN (SELECT order_id FROM vw_pedidos_validos)) GROUP BY categoria_ingles ORDER BY porcentaje DESC LIMIT 1"
}
